-- LUMA — Thème 7 : LONG 1/3 x4 — Une session shopping avec plusieurs boutiques et décisions
-- ============================================


update scenarios set content = '{"characters": {"friend": "ton ami(e)", "clerk1": "vendeur 1", "clerk3": "vendeur 3"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "Okay, we have the whole afternoon to find you the perfect outfit for the gala!", "text_fr": "Bon, on a tout l''après-midi pour te trouver la tenue parfaite pour le gala !", "choices": [{"text": "I''m excited, though a bit overwhelmed with all the options out there.", "text_fr": "Je suis excité, même si un peu dépassé par toutes les options.", "next": "n2"}, {"text": "Let''s do this! I trust your taste more than mine, honestly.", "text_fr": "Allons-y ! Je fais plus confiance à ton goût qu''au mien, honnêtement.", "next": "n2b"}]}, "n2": {"speaker": "friend", "text": "Don''t worry, we''ll take it store by store. Let''s start here!", "text_fr": "T''inquiète, on va faire ça magasin par magasin. Commençons ici !", "choices": [{"text": "Sounds good, lead the way.", "text_fr": "Ça marche, montre le chemin.", "next": "n3"}]}, "n2b": {"speaker": "friend", "text": "Ha, I''ll definitely help, but it still has to feel like you in the end.", "text_fr": "Ha, je vais définitivement aider, mais ça doit quand même te ressembler à la fin.", "choices": [{"text": "Fair point, let''s find that balance together.", "text_fr": "Bon point, trouvons cet équilibre ensemble.", "next": "n3"}]}, "n3": {"speaker": "clerk1", "text": "Welcome! Looking for anything special today?", "text_fr": "Bienvenue ! Vous cherchez quelque chose de spécial aujourd''hui ?", "choices": [{"text": "Yes, a formal outfit for a gala event.", "text_fr": "Oui, une tenue formelle pour un événement de gala.", "next": "n4"}]}, "n4": {"speaker": "clerk1", "text": "We have a lovely selection in the back, let me show you.", "text_fr": "On a une belle sélection à l''arrière, laissez-moi vous montrer.", "choices": [{"text": "(Try on the first option, a deep blue suit.)", "text_fr": "(Essaie la première option, un costume bleu profond.)", "next": "n5"}]}, "n5": {"speaker": "friend", "text": "(Sees the blue suit) Ooh, I like this one, but let''s see other stores before deciding.", "text_fr": "(Voit le costume bleu) Ooh, j''aime bien celui-là, mais voyons d''autres magasins avant de décider.", "choices": [{"text": "Agreed, this is nice but let''s keep our options open.", "text_fr": "D''accord, c''est joli mais gardons nos options ouvertes.", "next": "n6"}, {"text": "Actually, I really love this one already, should we just get it?", "text_fr": "En fait, j''adore déjà celui-là, on devrait juste le prendre ?", "next": "n6b"}]}, "n6": {"speaker": "you_thought", "text": "(You head to a second boutique with more modern, edgy pieces.)", "text_fr": "(Vous vous dirigez vers une deuxième boutique avec des pièces plus modernes et audacieuses.)", "choices": [{"text": "(Try on a sleek black outfit with a modern cut.)", "text_fr": "(Essaie une tenue noire élégante avec une coupe moderne.)", "next": "n7"}]}, "n6b": {"speaker": "friend", "text": "I get the excitement, but trust me, seeing more options helps you feel confident in your choice.", "text_fr": "Je comprends l''excitation, mais crois-moi, voir plus d''options t''aide à te sentir confiant dans ton choix.", "choices": [{"text": "You''re right, let''s keep exploring a bit more.", "text_fr": "T''as raison, continuons à explorer un peu plus.", "next": "n7"}]}, "n7": {"speaker": "friend", "text": "(Studying the black outfit intently) Hmm, this is sleek, but I''m not sure it says ''you'' as much.", "text_fr": "(Étudiant la tenue noire attentivement) Hmm, c''est élégant, mais je suis pas sûr que ça te ressemble autant.", "choices": [{"text": "You might be right, it feels a bit too edgy for my style.", "text_fr": "T''as peut-être raison, ça semble un peu trop audacieux pour mon style.", "next": "n8"}, {"text": "I actually really like how different it feels — let''s keep it as an option.", "text_fr": "J''aime en fait vraiment à quel point c''est différent — gardons-le comme option.", "next": "n8b"}]}, "n8": {"speaker": "you_thought", "text": "(You head to a third boutique, this one known for classic, timeless pieces.)", "text_fr": "(Vous vous dirigez vers une troisième boutique, connue pour ses pièces classiques et intemporelles.)", "choices": [{"text": "(Try on a deep burgundy suit with subtle detailing.)", "text_fr": "(Essaie un costume bordeaux profond avec des détails subtils.)", "next": "n9"}]}, "n8b": {"speaker": "you_thought", "text": "(You keep the black outfit as a strong contender and continue to a third store.)", "text_fr": "(Vous gardez la tenue noire comme sérieuse candidate et continuez vers un troisième magasin.)", "choices": [{"text": "(Try on a burgundy suit here too, for comparison.)", "text_fr": "(Essaie aussi un costume bordeaux ici, pour comparer.)", "next": "n9"}]}, "n9": {"speaker": "friend", "text": "(Gasps) Okay, THIS one. This is the one, I can just tell.", "text_fr": "(Sursaute) OK, CELUI-LÀ. C''est le bon, je le sens.", "choices": [{"text": "(Look in the mirror) Wow, you might be right, this feels perfect.", "text_fr": "(Se regarde dans le miroir) Waouh, tu as peut-être raison, ça semble parfait.", "next": "n10"}, {"text": "It''s nice, but let me compare it with the other two options mentally first.", "text_fr": "C''est joli, mais laisse-moi comparer mentalement avec les deux autres options d''abord.", "next": "n10b"}]}, "n10": {"speaker": "clerk3", "text": "That color really suits your complexion, if I may say.", "text_fr": "Cette couleur vous va vraiment bien, si je peux me permettre.", "choices": [{"text": "Thank you, I think this might genuinely be the one.", "text_fr": "Merci, je pense que ça pourrait vraiment être le bon.", "next": "n11"}]}, "n10b": {"speaker": "friend", "text": "Take your time — but honestly, the way you''re standing differently in this one says a lot.", "text_fr": "Prends ton temps — mais honnêtement, la façon dont tu te tiens différemment dans celui-ci en dit long.", "choices": [{"text": "(Look again) You know, you''re right, I do feel more confident in this.", "text_fr": "(Regarde encore) Tu sais, t''as raison, je me sens plus confiant dans celui-ci.", "next": "n11"}]}, "n11": {"speaker": "you_thought", "text": "(After three stores and countless outfits, this burgundy suit finally feels right.)", "text_fr": "(Après trois magasins et d''innombrables tenues, ce costume bordeaux semble enfin le bon.)", "choices": [{"text": "This is definitely the one, let''s get it.", "text_fr": "C''est définitivement le bon, prenons-le.", "next": "n12"}]}, "n12": {"speaker": "friend", "text": "I''m so glad we took the time to look around — this suits you perfectly.", "text_fr": "Je suis tellement content qu''on ait pris le temps de regarder — ça te va parfaitement.", "choices": [{"text": "Me too, thank you for your patience and honest opinions all day.", "text_fr": "Moi aussi, merci pour ta patience et tes avis honnêtes toute la journée.", "next": "end_perfect"}]}, "end_perfect": {"speaker": "friend", "text": "That''s what friends are for! You''re going to turn heads at that gala.", "text_fr": "C''est à ça que servent les amis ! Tu vas faire tourner des têtes à ce gala.", "end": true, "ending_label": "La tenue parfaite trouvée après une vraie recherche 🕴️✨"}}}'::jsonb, is_playable = true
where title = 'Une session shopping avec plusieurs boutiques et décisions'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));
